//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Zero is treated as one.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry number, where 0 is the first retry.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        self.base_delay_ms
            .saturating_mul(2u64.saturating_pow(retry_number))
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_saturates_without_overflowing() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX - 1,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX - 1);
    }

    #[test]
    fn delay_is_capped_at_configured_maximum() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };

        assert_eq!(config.delay_for_retry(0), 10);
        assert_eq!(config.delay_for_retry(1), 20);
        assert_eq!(config.delay_for_retry(2), 25);
        assert_eq!(config.delay_for_retry(3), 25);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);

    for attempt in 0..max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempt + 1 < max_attempts => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
            }
            Err(error) => return Err(error),
        }
    }

    unreachable!("max_attempts is always at least one")
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("temporary failure".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn returns_permanent_errors_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let error = RetryError::Permanent("invalid input".into());

        let result = run_job(&config(4, 10, 25), &mut sleeper, || {
            calls += 1;
            Err(error.clone())
        });

        assert_eq!(result, Err(error));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(2, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still unavailable".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![10]);
    }

    #[test]
    fn zero_attempt_budget_still_makes_one_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(0, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("failure".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("failure".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_until_success() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 7,
        max_delay_ms: 50,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 | 2 => Err(RetryError::Transient("service unavailable".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![7, 14]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 7,
        max_delay_ms: 50,
    };
    let mut sleeper = FakeSleeper::default();
    let expected = RetryError::Permanent("bad request".into());
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(expected.clone())
    });

    assert_eq!(result, Err(expected));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}
